//! Scan result types (PLAN.md section 3). TS bindings are generated by `ts-rs`.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct VolumeInfo {
    #[ts(type = "number")]
    pub total: u64,
    #[ts(type = "number")]
    pub available: u64,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct NodeFlags {
    pub inaccessible: bool,
    pub symlink: bool,
    pub mount: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct FileLeaf {
    pub name: String,
    #[ts(type = "number")]
    pub size: u64,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct DirNode {
    pub id: u32,
    pub parent: Option<u32>,
    pub name: String,
    /// Allocated size (`st_blocks * 512`), aggregated over the subtree.
    #[ts(type = "number")]
    pub size: u64,
    #[ts(type = "number")]
    pub logical_size: u64,
    #[ts(type = "number")]
    pub file_count: u64,
    pub children: Vec<u32>,
    pub top_files: Vec<FileLeaf>,
    pub flags: NodeFlags,
    /// Resolved in Phase 3; empty after scanning.
    pub category: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct SnapshotMeta {
    pub id: String,
    pub root: String,
    #[ts(type = "number")]
    pub scanned_at: i64,
    #[ts(type = "number")]
    pub duration_ms: u64,
    pub volume: VolumeInfo,
    #[ts(type = "number")]
    pub scanned_size: u64,
    pub inaccessible_count: u32,
}

/// Arena of directories; index = `DirNode::id`, root is index 0.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Snapshot {
    pub meta: SnapshotMeta,
    pub nodes: Vec<DirNode>,
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(tag = "event", content = "data", rename_all = "camelCase")]
#[ts(export)]
pub enum ScanEvent {
    Progress {
        #[ts(type = "number")]
        files: u64,
        #[ts(type = "number")]
        bytes: u64,
        current: String,
    },
    Finished {
        meta: SnapshotMeta,
    },
    Failed {
        message: String,
    },
}
